SELECT 
FROM sys_process_transition_flow


        AND orchestration_config_id = #{orchestrationConfigId}


        AND event_config_id = #{eventConfigId}


        AND process_def_key LIKE CONCAT('%', #{processDefKey}, '%')


        AND process_def_unique_key = #{processDefUniqueKey}


        AND node_def_key LIKE CONCAT('%', #{nodeDefKey}, '%')


        AND process_instance_id = #{processInstanceId}


        AND process_instance_sequence = #{processInstanceSequence}


        AND business_description LIKE CONCAT('%', #{businessDescription}, '%')


        AND business_id = #{businessId}


        AND from_node = #{fromNode}


        AND to_node = #{toNode}


        AND transition_type = #{transitionType}


        AND transition_result = #{transitionResult}


        AND create_user_id = #{createUserId}


        AND update_user_id = #{updateUserId}


        AND create_time >= #{createTime}


        AND update_time >= #{updateTime}


ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

